import{C as a}from"./chunks/ContainerGuide.CD6rK92e.js";import{o,a as s,d as t,H as n}from"./chunks/framework.MWxrmMMs.js";import"./chunks/theme.CZQCAeZ1.js";const h=JSON.parse('{"title":"Console version","description":"stuzhik-cli: Stuzhik without a window for Minecraft servers on Linux. One file with no dependencies, .deb and .rpm packages, a systemd service, a container, backups and modpack updates from a terminal.","frontmatter":{"platform":"Linux","description":"stuzhik-cli: Stuzhik without a window for Minecraft servers on Linux. One file with no dependencies, .deb and .rpm packages, a systemd service, a container, backups and modpack updates from a terminal.","head":[["meta",{"name":"keywords","content":"stuzhik-cli, minecraft server linux, minecraft server systemd, modpack server, minecraft server docker, raspberry pi minecraft server"}]]},"headers":[],"relativePath":"en/guide/cli.md","filePath":"en/guide/cli.md"}'),d={name:"en/guide/cli.md"},u=Object.assign(d,{setup(r){return(c,e)=>(o(),s("div",null,[e[0]||(e[0]=t(`<h1 id="console-version" tabindex="-1">Console version <a class="header-anchor" href="#console-version" aria-label="Permalink to &quot;Console version&quot;">​</a></h1><p><code>stuzhik-cli</code> is Stuzhik without a window: Minecraft servers from a terminal, as a systemd service or in a container. It is one file with no dependencies for any Linux on x86_64 and on ARM (aarch64: Raspberry Pi 4 and newer, ARM servers).</p><p>It works on the same data as the window app: a server created in the window runs from the terminal, and the other way round.</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>The files for x86_64 and ARM, and the commands that download and install them, are on the <a href="/en/download.html#cli">download page</a>. For ARM the names say <code>arm64</code> or <code>aarch64</code> instead of <code>amd64</code> and <code>x86_64</code>.</p><table tabindex="0"><thead><tr><th>System</th><th>How to install</th></tr></thead><tbody><tr><td>Debian, Ubuntu, Mint</td><td><code>sudo apt install ./stuzhik-cli_*_amd64.deb</code></td></tr><tr><td>Fedora, RHEL, Alma, Rocky</td><td><code>sudo dnf install ./stuzhik-cli-*.x86_64.rpm</code></td></tr><tr><td>openSUSE</td><td><code>sudo rpm -i ./stuzhik-cli-*.x86_64.rpm</code></td></tr><tr><td>Arch and any other</td><td><code>tar xzf stuzhik-cli-*-x86_64-linux.tar.gz</code>, then <code>sudo install -m 0755 stuzhik-cli-*-x86_64-linux/stuzhik-cli /usr/local/bin/</code></td></tr></tbody></table><p>The packages are not signed yet: dnf warns «skipped OpenPGP checks», which is expected. The files can be checked against <a href="/en/download.html#checksums">SHA256SUMS</a>: <code>sha256sum -c SHA256SUMS --ignore-missing</code>.</p><p>The launcher downloads Java for the server by itself. It is built for glibc: on Alpine and other musl systems you need the <code>gcompat</code> package or your own Java in the build&#39;s settings.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> create</span><span style="color:#9ECBFF;"> &quot;My server&quot;</span><span style="color:#79B8FF;"> --mc</span><span style="color:#79B8FF;"> 1.21.1</span><span style="color:#79B8FF;"> --loader</span><span style="color:#9ECBFF;"> fabric</span><span style="color:#79B8FF;"> --accept-eula</span></span>
<span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> run</span><span style="color:#9ECBFF;"> &quot;My server&quot;</span></span></code></pre></div><p>The server console is in the same terminal: type commands as usual. Ctrl+C stops the server with <code>stop</code> (the world is saved), a second Ctrl+C ends it at once.</p><p>A build can be named by its id, its name or the start of either.</p><h2 id="a-server-from-a-modpack" tabindex="-1">A server from a modpack <a class="header-anchor" href="#a-server-from-a-modpack" aria-label="Permalink to &quot;A server from a modpack&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> create</span><span style="color:#9ECBFF;"> &quot;Pack&quot;</span><span style="color:#79B8FF;"> --modpack</span><span style="color:#9ECBFF;"> ./pack.mrpack</span><span style="color:#79B8FF;"> --accept-eula</span></span></code></pre></div><p>The modpack comes from a file (<code>.mrpack</code>, a CurseForge <code>.zip</code>, <code>.stzhk</code>), an address on modrinth.com, <code>modrinth:&lt;project&gt;[@&lt;version&gt;]</code> or <code>curseforge:&lt;project id&gt;[@&lt;file id&gt;]</code>. It is installed as a server right away, without the game&#39;s client files, and the pack&#39;s client mods are turned off. Mods it could not find out about are listed at the end, so you can check them by hand.</p><p>Updating the pack:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> update</span><span style="color:#9ECBFF;"> &quot;Pack&quot;</span></span></code></pre></div><p>First you see what will change: which mods are added, updated and removed. It is applied after «yes». A backup is made before the update (<code>--no-backup</code> skips it), configs already there stay (<code>--overwrite-configs</code> replaces them with the pack&#39;s), <code>--to</code> picks the version. Updating to a pack version for another game version is done only in the window: there it can be rolled back.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>list</code>, <code>info &lt;build&gt;</code></td><td>builds and details (<code>--json</code> for scripts)</td></tr><tr><td><code>create &lt;name&gt; --mc &lt;version&gt; [--loader …] [--port] [--memory MB] [--accept-eula]</code></td><td>create and install a server</td></tr><tr><td><code>create &lt;name&gt; --modpack &lt;pack&gt;</code></td><td>a server from a modpack</td></tr><tr><td><code>run &lt;build&gt;</code></td><td>run in this terminal</td></tr><tr><td><code>console &lt;build&gt;</code></td><td>the console of a server that <code>run</code> holds in another terminal or as a service</td></tr><tr><td><code>tui</code></td><td>a terminal screen: builds, the server console and its server.properties</td></tr><tr><td><code>update &lt;build&gt;</code></td><td>update the build&#39;s modpack, with a preview</td></tr><tr><td><code>backup &lt;build&gt;</code>, <code>backups &lt;build&gt;</code>, <code>restore &lt;backup&gt; [--worlds]</code></td><td>backups</td></tr><tr><td><code>eula &lt;build&gt; [--accept]</code>, <code>props &lt;build&gt; [key=value…]</code></td><td>EULA and server.properties</td></tr><tr><td><code>analyze &lt;build or log file&gt;</code></td><td>log analysis: problems and what to do</td></tr><tr><td><code>service &lt;build&gt; [--install] [--system]</code></td><td>a systemd service</td></tr><tr><td><code>paths</code></td><td>where the data is</td></tr></tbody></table><p>Loaders: <code>vanilla</code>, <code>fabric</code>, <code>quilt</code>, <code>forge</code>, <code>neoforge</code>. All commands and options: <code>stuzhik-cli --help</code>.</p><h2 id="a-systemd-service" tabindex="-1">A systemd service <a class="header-anchor" href="#a-systemd-service" aria-label="Permalink to &quot;A systemd service&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> service</span><span style="color:#9ECBFF;"> &quot;My server&quot;</span><span style="color:#79B8FF;"> --install</span></span>
<span class="line"><span style="color:#B392F0;">systemctl</span><span style="color:#79B8FF;"> --user</span><span style="color:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="color:#B392F0;">systemctl</span><span style="color:#79B8FF;"> --user</span><span style="color:#9ECBFF;"> enable</span><span style="color:#79B8FF;"> --now</span><span style="color:#9ECBFF;"> stuzhik-</span><span style="color:#F97583;">&lt;</span><span style="color:#9ECBFF;">nam</span><span style="color:#E1E4E8;">e</span><span style="color:#F97583;">&gt;</span></span>
<span class="line"><span style="color:#B392F0;">loginctl</span><span style="color:#9ECBFF;"> enable-linger</span><span style="color:#E1E4E8;"> $USER</span></span></code></pre></div><p>The first command prints the exact name of the service. <code>enable-linger</code> keeps the server running while you are logged out; <code>--system</code> writes a system service (needs root), which runs as the current user.</p><p><code>systemctl stop</code> saves the world: the server gets <code>stop</code> rather than being cut off. A crashed server restarts by itself, while a setup error (an EULA not accepted, for example) does not, so the service doesn&#39;t spin uselessly.</p><p>The console of a running service: <code>stuzhik-cli console &quot;My server&quot;</code> shows the last lines of output, then live ones, and your commands go to the server. Ctrl+C only detaches the console; the server keeps running.</p><h2 id="a-container" tabindex="-1">A container <a class="header-anchor" href="#a-container" aria-label="Permalink to &quot;A container&quot;">​</a></h2><p>The image is built from the console version archive, the same way on Podman and on Docker. The server&#39;s data lives in the <code>stuzhik</code> volume and survives recreating the container.</p>`,28)),n(a),e[1]||(e[1]=t('<p>To leave the console with the server running: Ctrl+P, then Ctrl+Q. <code>stop</code> (or <code>podman stop mc</code>, <code>docker stop mc</code>) saves the world: the container gets 120 seconds for it.</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>By default it is the same folder as the window app&#39;s. Another one: <code>--data-dir /srv/stuzhik</code> or the variable <code>STUZHIK_DATA=/srv/stuzhik</code>.</p><p>While a command is running, the window does not move the data folder to another disk and says why, and a command started in the middle of a move will not wait: it asks you to let the move finish.</p><h2 id="language-and-exit-codes" tabindex="-1">Language and exit codes <a class="header-anchor" href="#language-and-exit-codes" aria-label="Permalink to &quot;Language and exit codes&quot;">​</a></h2><p>Messages follow the system language; <code>STUZHIK_LANG=ru</code> or <code>en</code> sets it explicitly (a server often has <code>C</code>, which means Russian).</p><p>Exit codes: 0 done, 1 the server crashed, 2 a refusal (no such build, EULA not accepted, a wrong option), 3 <code>analyze</code> found a critical problem. The service relies on them: code 2 is not restarted.</p>',7))]))}});export{h as __pageData,u as default};
